var NM={578:"Norway",752:"Sweden",591:"Panama",840:"United States",152:"Chile",404:"Kenya",554:"New Zealand",304:"Greenland",246:"Finland",826:"United Kingdom",356:"India",32:"Argentina",10:"Antarctica",36:"Australia",646:"Rwanda",710:"South Africa",218:"Ecuador",72:"Botswana",100:"Bulgaria",348:"Hungary",528:"Netherlands",156:"China",191:"Croatia",643:"Russia",250:"France",208:"Denmark",352:"Iceland",276:"Germany",724:"Spain",620:"Portugal",380:"Italy",40:"Austria",56:"Belgium",756:"Switzerland",372:"Ireland",616:"Poland",300:"Greece",203:"Czech Republic",642:"Romania",688:"Serbia",703:"Slovakia",705:"Slovenia",233:"Estonia",428:"Latvia",440:"Lithuania",804:"Ukraine",8:"Albania",70:"Bosnia and Herzegovina",499:"Montenegro",807:"North Macedonia"};
